{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Add a pairwise ranking term weighted by 0.2 to the existing pointwise logistic loss across all four datasets. Preserve valid-position averaging, sampling, architecture, scoring, optimizer, training settings, and one checkpoint per category. Predictor and checkpoint shapes remain unchanged.",
      "edits": [
        {
          "find": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    loss = (\n        nn.functional.softplus(-pos_scores)\n        + nn.functional.softplus(neg_scores)\n        + 0.2 * nn.functional.softplus(neg_scores - pos_scores)\n    )\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Augment pointwise logistic loss with a 0.2-weighted pairwise softplus ranking loss over the same valid target positions."
}
